import React from 'react';

import type { DataTestId } from '../../../../core/types/data-props.js';
import type { StylingProps } from '../../../../core/types/styling-props.js';
import type { WithChildren } from '../../../../core/types/with-children.js';
import { _BaseItem as BaseItem } from '../form-field-messages/FormFieldMessageBaseItem.js';

export interface HintProps extends WithChildren, StylingProps, DataTestId {
  /**
   * Whether the connected input is currently in an error state.
   * @deprecated When adding an error to a form control, please use a FormFieldMessage.Item inside a FormFieldMessage component.
   */
  hasError?: boolean;
  /**
   * Whether the connected input is currently disabled.
   * @defaultValue false
   */
  disabled?: boolean;
  /** Id to link the hint to its corresponding element. */
  id?: string;
}

/** Renders a hint message if given, otherwise renders nothing. */
export const Hint = (props: HintProps) => {
  const { children, hasError = false, ...remainingProps }: HintProps = props;

  return children ? (
    <BaseItem variant={hasError ? 'error' : 'hint'} {...remainingProps}>
      {children}
    </BaseItem>
  ) : null;
};

Hint.displayName = 'Hint';
